var t=`1374-quesillo`;var a=`world-1374`;var n=`VE`;var r=`south-america`;var o=8;var l=256;var s={en:`Quesillo`,ua:`Кесільйо`};var d={en:`Quesillo is a dish from Venezuela featuring chicken egg, sweetened condensed milk, whole cow milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Кесільйо, страва кухні країни Венесуела з такими основними складниками: куряче яйце, згущене молоко з цукром, цільне коров'яче молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var m=[{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 9 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 9 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:9,i:[[`white-granulated-sugar`,160,`g`],[`water`,55,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`chicken-egg`,6,`pcs`],[`sweetened-condensed-milk`,390,`g`],[`whole-cow-milk`,530,`ml`],[`vanilla-extract`,6,`ml`]]},{en:`Place the caramel-lined custard mold into a hot water bath and bake at 160°C until the custard is cooked and just set.`,ua:`Поставте форму з карамеллю та кремом у гарячу водяну баню й випікайте при 160°C до готовності та застигання крему.`,t:[`poaching`],m:55,i:[]},{en:`Refrigerate the prepared mixture for about 180 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 180 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:180,i:[]}];var u={slug:t,id:a,country:`VE`,region:r,servings:8,minutes:256,title:s,text:d,steps:m};export{n as country,u as default,a as id,l as minutes,r as region,o as servings,t as slug,m as steps,d as text,s as title};